[{"request_id": "dialogue-109", "events": [{"role": "user", "content": "Nate: Pets really seem to do that to everyone don't they! So, what about your script now? Any ideas for the next steps?", "speaker": "Nate", "occurred_at": "2022-03-18T18:59:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_7299c7bc156241a18ed8128b57e88374", "session_id": "session_d23aea3af43a4c78b19c8ed85c91f50f", "sequence": 109}, {"request_id": "dialogue-110", "events": [{"role": "user", "content": "Joanna: I've been doing my fair share of research and networking non-stop for it. It's tough, but I'm determined to make it happen.", "speaker": "Joanna", "occurred_at": "2022-03-18T18:59:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_ca6df41215e640ed90152c588dd1f323", "session_id": "session_d23aea3af43a4c78b19c8ed85c91f50f", "sequence": 110}, {"request_id": "dialogue-111", "events": [{"role": "user", "content": "Nate: Great idea! that should hopefully get some more eyes on it. Keep up the hard work!", "speaker": "Nate", "occurred_at": "2022-03-18T18:59:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_749933a9f8ff43929f6a157adc85986d", "session_id": "session_d23aea3af43a4c78b19c8ed85c91f50f", "sequence": 111}, {"request_id": "dialogue-112", "events": [{"role": "user", "content": "Joanna: Thanks so much, Nate! Your support means a lot. I'll keep working at it and hopefully the next steps will become clearer soon.", "speaker": "Joanna", "occurred_at": "2022-03-18T18:59:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_3af81bb4c9eb438fadb93498771d81b6", "session_id": "session_d23aea3af43a4c78b19c8ed85c91f50f", "sequence": 112}, {"request_id": "dialogue-113", "events": [{"role": "user", "content": "Nate: Just make sure you don't quit - the path forward will show up soon. You got this!", "speaker": "Nate", "occurred_at": "2022-03-18T18:59:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_d61d6ff420884f84a6fa90436d0d60e7", "session_id": "session_d23aea3af43a4c78b19c8ed85c91f50f", "sequence": 113}, {"request_id": "dialogue-114", "events": [{"role": "user", "content": "Joanna: Appreciated! I think just having someone to support me throughout the whole process is such a blessing. It gives me the motivation to keep pushing forward.", "speaker": "Joanna", "occurred_at": "2022-03-18T18:59:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_d2cee7fdecfb49c3ad0053059e044f61", "session_id": "session_d23aea3af43a4c78b19c8ed85c91f50f", "sequence": 114}, {"request_id": "dialogue-115", "events": [{"role": "user", "content": "Nate: Glad to hear my support makes a difference, Joanna. I'm here for you!", "speaker": "Nate", "occurred_at": "2022-03-18T18:59:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_c2a3c45caab34db38ee5f096a03120ee", "session_id": "session_d23aea3af43a4c78b19c8ed85c91f50f", "sequence": 115}, {"request_id": "dialogue-116", "events": [{"role": "user", "content": "Joanna: [Image: a photo of a cinema ticket on a chair] Always good to hear! See you later!", "speaker": "Joanna", "occurred_at": "2022-03-18T18:59:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_78d546354cc848d3b2d6377cec7b9dcf", "session_id": "session_d23aea3af43a4c78b19c8ed85c91f50f", "sequence": 116}]
